package com.zenix.musicplayer;

import android.app.*;
import android.content.*;
import android.content.pm.ServiceInfo;
import android.graphics.*;
import android.os.*;
import android.provider.Settings;
import android.view.*;
import android.widget.*;
import androidx.core.app.NotificationCompat;
import org.json.*;

/** Independent user-enabled character window; it never takes ownership of audio. */
public final class AssistantOverlayService extends Service {
    static final String OPEN_ASSISTANT_EXTRA="zenix.openAssistant";
    private static volatile boolean active;
    private WindowManager manager;private WindowManager.LayoutParams params;private CharacterView view;private final java.util.concurrent.ExecutorService loader=java.util.concurrent.Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());private boolean destroyed;
    private float downX,downY;private int startX,startY;private boolean moved,locked;private ZenixRuntime runtime;
    static boolean running(){return active;}
    private int dp(float value){return Math.round(value*getResources().getDisplayMetrics().density);}
    @Override public void onCreate(){super.onCreate();runtime=ZenixRuntime.get(this);if(!Settings.canDrawOverlays(this)){stopSelf();return;}String channel="zenix-music-assistant";NotificationManager notifications=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26)notifications.createNotificationChannel(new NotificationChannel(channel,"音乐助手悬浮",NotificationManager.IMPORTANCE_LOW));PendingIntent close=PendingIntent.getService(this,2114,new Intent(this,AssistantOverlayService.class).setAction("close"),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);PendingIntent home=PendingIntent.getActivity(this,2115,new Intent(this,MainActivity.class).putExtra(OPEN_ASSISTANT_EXTRA,true),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification notification=new NotificationCompat.Builder(this,channel).setSmallIcon(R.drawable.zenix_icon).setContentTitle("Zenix 音乐助手").setContentText("轻触返回，长按打开操作；可随时关闭").setContentIntent(home).setSilent(true).setOngoing(true).addAction(0,"关闭助手",close).build();if(Build.VERSION.SDK_INT>=34)startForeground(2113,notification,ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE);else startForeground(2113,notification);manager=(WindowManager)getSystemService(WINDOW_SERVICE);params=new WindowManager.LayoutParams(dp(108),dp(108),Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL,PixelFormat.TRANSLUCENT);params.gravity=Gravity.TOP|Gravity.START;params.x=dp(12);params.y=dp(180);view=new CharacterView();try{manager.addView(view,params);active=true;}catch(Exception error){stopSelf();return;}view.setOnLongClickListener(v->{menu();return true;});view.setOnTouchListener((v,event)->{switch(event.getActionMasked()){case MotionEvent.ACTION_DOWN:downX=event.getRawX();downY=event.getRawY();startX=params.x;startY=params.y;moved=false;return false;case MotionEvent.ACTION_MOVE:if(!locked&&(Math.abs(event.getRawX()-downX)>dp(5)||Math.abs(event.getRawY()-downY)>dp(5))){moved=true;params.x=Math.max(0,Math.min(getResources().getDisplayMetrics().widthPixels-params.width,startX+(int)(event.getRawX()-downX)));params.y=Math.max(0,Math.min(getResources().getDisplayMetrics().heightPixels-params.height,startY+(int)(event.getRawY()-downY)));manager.updateViewLayout(view,params);return true;}break;case MotionEvent.ACTION_UP:if(moved)return true;break;}return false;});view.setOnClickListener(v->startActivity(new Intent(this,MainActivity.class).putExtra(OPEN_ASSISTANT_EXTRA,true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP)));}
    @Override public int onStartCommand(Intent intent,int flags,int id){if(intent!=null&&"close".equals(intent.getAction())){stopSelf();return START_NOT_STICKY;}if(params!=null&&intent!=null){int size=dp(Math.max(64,Math.min(220,intent.getIntExtra("size",108))));params.width=size;params.height=size;manager.updateViewLayout(view,params);}return START_NOT_STICKY;}
    private void menu(){PopupMenu menu=new PopupMenu(this,view);for(String label:new String[]{"播放／暂停","上一首","下一首",locked?"解锁位置":"锁定位置","关闭助手"})menu.getMenu().add(label);menu.setOnMenuItemClickListener(item->{String label=item.getTitle().toString();try{if(label.equals("关闭助手"))stopSelf();else if(label.contains("位置"))locked=!locked;else if(runtime.service!=null){if(label.equals("播放／暂停"))runtime.service.toggle();else runtime.service.advance(label.equals("上一首")?-1:1);}}catch(Exception ignored){}return true;});menu.show();}
    @Override public void onDestroy(){active=false;destroyed=true;loader.shutdownNow();if(view!=null)try{manager.removeView(view);}catch(Exception ignored){}super.onDestroy();}
    @Override public IBinder onBind(Intent intent){return null;}
    private final class CharacterView extends View {
        private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);private Bitmap image;
        CharacterView(){super(AssistantOverlayService.this);setContentDescription("Zenix 音乐助手，轻触返回，长按操作");loader.execute(()->{try{JSONObject skin=new AssistantFeatures(AssistantOverlayService.this).skin();if(skin!=null){JSONObject config=skin.getJSONObject("config");JSONArray frames=config.getJSONArray("frames"),idle=config.getJSONObject("animations").getJSONObject("idle").getJSONArray("frames");String file=frames.getString(idle.getInt(0));byte[] data=android.util.Base64.decode(skin.getJSONObject("images").getString(file),android.util.Base64.NO_WRAP);BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=Math.max(1,config.optInt("width",180)/256);Bitmap decoded=BitmapFactory.decodeByteArray(data,0,data.length,options);main.post(()->{if(destroyed){if(decoded!=null)decoded.recycle();return;}image=decoded;invalidate();});}}catch(Exception ignored){}});}
        @Override protected void onDraw(Canvas canvas){super.onDraw(canvas);if(image!=null){canvas.drawBitmap(image,null,new RectF(0,0,getWidth(),getHeight()),paint);return;}float unit=getWidth()/180f;canvas.save();canvas.scale(unit,unit);paint.setColor(Color.rgb(216,229,250));canvas.drawOval(23,30,157,163,paint);paint.setColor(Color.rgb(166,186,219));Path ears=new Path();ears.moveTo(35,65);ears.lineTo(30,15);ears.lineTo(75,43);ears.moveTo(105,43);ears.lineTo(150,15);ears.lineTo(145,65);canvas.drawPath(ears,paint);paint.setColor(Color.rgb(38,51,73));canvas.drawOval(60,84,73,104,paint);canvas.drawOval(107,84,120,104,paint);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(5);canvas.drawArc(76,106,105,132,0,180,false,paint);paint.setStyle(Paint.Style.FILL);canvas.restore();}
        @Override protected void onDetachedFromWindow(){if(image!=null){image.recycle();image=null;}super.onDetachedFromWindow();}
    }
}
